#nullable enable // autogenerated

using PVZEngine.Tools.Unity;
using UnityEngine;

namespace MVZ2Logic.UI
{
    [DisallowMultipleComponent]
    [RequireComponent(typeof(ParticleSystem))]
    public class ParticleRendererResolver : MonoBehaviour, ISpriteResolver
    {
        private void OnEnable()
        {
            if (!spriteChanged)
            {
                spriteChanged = true;
                var textures = System.textureSheetAnimation;
                BaseSprites = new Sprite?[textures.spriteCount];
                for (int i = 0; i < BaseSprites.Length; i++)
                {
                    BaseSprites[i] = textures.GetSprite(i);
                }
            }
            if (BaseSprites != null)
            {
                SetSprites(BaseSprites);
            }
        }
        public virtual void SetSprites(Sprite?[] sprites)
        {
            if (Global.Resources != null)
            {
                var textures = System.textureSheetAnimation;
                for (int i = 0; i < sprites.Length; i++)
                {
                    var sprite = sprites[i];
                    if (sprite.Exists())
                    {
                        textures.SetSprite(i, Global.Resources.GetFinalSprite(sprite));
                    }
                }
            }
            spriteChanged = true;
            BaseSprites = sprites;
        }
        public Sprite?[]? BaseSprites { get; private set; }
        public ParticleSystem System
        {
            get
            {
                if (!_system.Exists())
                {
                    _system = GetComponent<ParticleSystem>();
                }
                return _system;
            }
        }
        private ParticleSystem? _system;
        private bool spriteChanged;
    }
}
